import { expect, Journey, test } from './journey.js';

test("gotoPath opens an address, with a fragment if it has one", async ({ browser, baseURL, page, context }) => {
  const j = await Journey.start({ browser, baseURL, page, context }, [], { logs: false });
  try {
    await j.goto("/p/basic");
    expect(j.response?.status(), "the status of the last navigation").toBe(200);
    await j.goto("/p/fragment" + "#i=abc&t=def");
    await j.expectText(null, j.text("Fragment #i=abc&t=def"), undefined);
  } finally {
    await j.close();
  }
});
